import { Question } from "@/lib/types";

function sample(f: (x: number) => number, xMin: number, xMax: number, n = 80): Array<[number, number]> {
  const pts: Array<[number, number]> = [];
  for (let i = 0; i < n; i++) {
    const x = xMin + (i / (n - 1)) * (xMax - xMin);
    pts.push([x, f(x)]);
  }
  return pts;
}

const COL_MOD = "#1d4ed8";   // primary V / modulus graph (blue)
const COL_PAR = "#dc2626";   // parabola / quadratic (red)
const COL_LINE = "#16a34a";  // auxiliary line y = k (green)
const COL_PT = "#7c3aed";    // labelled points (purple)

